#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int T;
	cin>>T;
	while(T--){
	    int n;
	    cin>>n;
	    int s=3*n;
	    vector<long long> arr(s);
	    for(auto &a: arr){
	        cin>>a;
	    }
	    
	    sort(arr.begin(), arr.end());
	    reverse(arr.begin(), arr.end());
	    
	    vector<long long> pre(s+1, 0);
	    for(int i=0; i<s; ++i){
	        pre[i+1]=pre[i]+arr[i];
	    }
	    long long ans=0;
	    
	    for(int i=0; i<=n; ++i){
	        int l=0;
	        int r=n-i;
	        while(l<r){
	            int c=(l+r)/2;
	            
	            int a=i+2*c;
	            int b=3*n-2*i-c;
	            
	            long long g=arr[a]+arr[a+1]-3LL*arr[b-1];
	            
	            if(g>0) l=c+1;
	            
	            else r=c;
	        }
	        
	        for(int j=max(0, l-2);
	        j<=min(n-i, l+2); ++j){
	            int p=i+2*j;
	            int q=3*n-2 * i-j;
	            
	            long long cur=6LL* pre[i]+4LL * (pre[p]-pre[i])+3LL*(pre[q]-pre[p]);
	            ans=max(ans, cur);
	        }
	    }
	    cout<<ans<<endl;
	}

}
